package com.example.lovenotes;
import android.app.*;import android.appwidget.*;import android.content.*;import android.net.Uri;import android.widget.RemoteViews;
public class LoveWidget extends AppWidgetProvider {
 static final String REFRESH="com.example.lovenotes.REFRESH";
 public static void refreshAll(Context c){Intent intent=new Intent(c,LoveWidget.class);intent.setAction(REFRESH);c.sendBroadcast(intent);}
 public void onUpdate(Context c,AppWidgetManager m,int[] ids){refreshAll(c);}
 public void onReceive(Context c,Intent intent){super.onReceive(c,intent);if(REFRESH.equals(intent.getAction())){PendingResult pending=goAsync();new Thread(()->{try{update(c);}finally{pending.finish();}}).start();}}
 static void update(Context c){String text="Open Love Notes Widget to connect your daily note.",date="A little love for today";boolean connected=false;try{String token=Connection.token(c);if(token!=null){org.json.JSONObject data=Connection.request("/api/widget-today",token,null);text=data.getJSONObject("note").getString("text");date="A little love · "+data.getString("date");connected=true;}}catch(Exception e){text="Open Love Notes to reconnect, or tap refresh when you’re online.";}AppWidgetManager manager=AppWidgetManager.getInstance(c);int[] ids=manager.getAppWidgetIds(new ComponentName(c,LoveWidget.class));for(int id:ids){RemoteViews views=new RemoteViews(c.getPackageName(),R.layout.widget);views.setTextViewText(R.id.widget_text,text);views.setTextViewText(R.id.widget_date,date);Intent open=connected?new Intent(Intent.ACTION_VIEW,Uri.parse(Connection.ORIGIN+"/?app=1")):new Intent(c,MainActivity.class);views.setOnClickPendingIntent(R.id.widget_root,PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));Intent refresh=new Intent(c,LoveWidget.class).setAction(REFRESH);views.setOnClickPendingIntent(R.id.widget_refresh,PendingIntent.getBroadcast(c,id,refresh,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));manager.updateAppWidget(id,views);}}
}
